"use client";

/**
 * Stat count: one number climbs to its value while a hairline under it fills,
 * then the label settles in. The proof beat of a launch film.
 *
 * Written by Better Design. Painted from the theme prop, so the number takes
 * the product's ink and the line takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

/** Frames the count takes. The label lands after it. */
const COUNT_FRAMES = 54;
const LABEL_AT = 46;
const LABEL_FRAMES = 18;

export interface StatCountProps {
  /** The figure the count lands on. Use a sourced number. */
  value?: number;
  /** Digits after the decimal point. */
  decimals?: number;
  prefix?: string;
  suffix?: string;
  /** One line that says what the number counts. */
  label?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const format = (n: number, decimals: number): string =>
  n.toLocaleString("en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals });

/** Count up to one sourced figure, with a filling rule under it and a label. */
export function StatCount({
  value = 12480,
  decimals = 0,
  prefix = "",
  suffix = "",
  label = "teams shipped a film this month",
  theme: themeOverride,
  font,
}: StatCountProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const progress = easings.out(interpolate(frame, [0, COUNT_FRAMES], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const shown = format(value * progress, decimals);
  // The final string sets the width, so the digits never shove the layout.
  const finalText = `${prefix}${format(value, decimals)}${suffix}`;

  const labelT = easings.out(interpolate(frame, [LABEL_AT, LABEL_AT + LABEL_FRAMES], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const rise = interpolate(frame, [0, 14], [24, 0], { extrapolateRight: "clamp" });
  const enter = interpolate(frame, [0, 10], [0, 1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 28, opacity: enter, transform: `translateY(${rise}px)` }}>
        <div style={{ position: "relative", fontSize: 168, fontWeight: 700, letterSpacing: "-0.04em", lineHeight: 1, color: theme.foreground, fontVariantNumeric: "tabular-nums" }}>
          <span style={{ visibility: "hidden" }}>{finalText}</span>
          <span style={{ position: "absolute", left: 0, top: 0 }}>{`${prefix}${shown}${suffix}`}</span>
        </div>
        <div style={{ width: "100%", height: 4, borderRadius: 2, background: withAlpha(theme.foreground, 0.08) }}>
          <div style={{ width: `${progress * 100}%`, height: "100%", borderRadius: 2, background: theme.primary }} />
        </div>
        <div style={{ fontSize: 40, fontWeight: 500, color: theme.mutedForeground, opacity: labelT, transform: `translateY(${(1 - labelT) * 12}px)` }}>
          {label}
        </div>
      </div>
    </AbsoluteFill>
  );
}
